      "@type": "FAQPage",
      "@id": "https://www.data4thepeople.com/p/what-is-driving-cpi#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Do the pieces add up?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. In every month, for both headline and core, our 204 items add up to within 0.0013 percentage points of the rate BLS publishes. The chart below compares the published rate (the line) with the sum of our items (the dots)."
          }
        },
        {
          "@type": "Question",
          "name": "What if health insurance and prescription drugs had risen at their usual pace?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Headline CPI would have been 3.9% instead of 3.7%, and core 2.8% instead of 2.6%. To find this, we swapped each one's actual 12-month change for its 10-year average and left every other item as published. The chart below compares the result with the published rates."
          }
        },
        {
          "@type": "Question",
          "name": "What is driving CPI inflation right now?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In September 2026, gasoline and shelter did most of the work. Gasoline, up 34.2% from a year earlier, added 1.09 points of the 3.7% rise in headline CPI. Shelter, mostly rent and owners' equivalent rent, added 1.14 points. Together they account for 60% of the increase."
          }
        },
        {
          "@type": "Question",
          "name": "What is driving core CPI?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Shelter. In September 2026, shelter added 1.43 of the 2.56 points in core CPI, or 56%. Owners' equivalent rent alone added 1.02 points. Airline fares added 0.25 and hospital services 0.15."
          }
        },
        {
          "@type": "Question",
          "name": "What is pulling CPI down?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In September 2026, motor vehicle insurance (down 5.0%), health insurance (down 9.0%), phones and similar devices (down 12.7%) and prescription drugs (down 4.5%) pulled headline CPI down the most, by 0.14, 0.08, 0.06 and 0.04 points. In all, 55 items with falling prices took 0.51 points off."
          }
        },
        {
          "@type": "Question",
          "name": "How much does gasoline add to CPI?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In September 2026, gasoline added 1.09 percentage points to the 3.7% rise in headline CPI, or 29% of it. Gasoline is about 3% of consumer spending in the CPI, but its price was 34.2% higher than a year earlier."
          }
        },
        {
          "@type": "Question",
          "name": "What does an item's contribution to CPI mean?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It is how many percentage points of the 12-month change in the CPI come from that item: its share of consumer spending times its own price change, adjusted for BLS's January weight update. The contributions of all 204 items add up to the published rate."
          }
        },
        {
          "@type": "Question",
          "name": "What is the difference between headline and core CPI?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Headline CPI covers all items. Core CPI leaves out food and energy. In September 2026, headline CPI was up 3.7% and core was up 2.6%."
          }
        },
        {
          "@type": "Question",
          "name": "Why is there no October 2025?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "BLS did not collect prices or publish a CPI for October 2025 during the federal funding lapse. It resumed collecting prices on November 14, 2025."
          }
        },
        {
          "@type": "Question",
          "name": "How often is the CPI Hot Air Balloon updated?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Each month, when BLS releases the CPI."
          }
        }
